//! Stippling: covering an area with many small touches of a brush tip.
//!
//! A stipple pass is many separate touches of a tip held upright: each
//! touch presses the tip into the canvas and lifts it, with no path between
//! touches. Touches fall on a jittered grid thinned by `coverage` (the mean
//! number of touches per point), optionally in clumps, and the tip is
//! reloaded from the palette every `dip_every` touches. The tone of the
//! passage is set by how densely the touches fall and by the paint's color,
//! hiding and thickness.
//!
//! Every touch is a `Touch` of a simulated `Held` brush (see `bristle`): it
//! deposits and lifts wet paint, so touches into a wet layer pick some of it
//! up and mix with it, and it dries with the rest of the wet layer
//! (Kubelka–Munk).
//!
//! ```ignore
//! // a region `m`, coverage falling from 1.2 at y = 0 to 0.2 at y = 800
//! let sp = Stipple::new(Tool::stippler(3.0)).mixed(&pal, 0.5)
//!     .color(|x, y| target(x, y)).coverage(|_, y| 1.2 - y / 800.0).pressure(0.4, 0.8);
//! c.stipple(&m, &sp, 1);
//! c.dry();
//! ```

use crate::bristle::{Bounds, Held, Rect, Tool, Touch, touch_footprint, touch_on};
use crate::canvas::Canvas;
use crate::color::{Rgb, from_oklab, to_oklab};
use crate::mask::Mask;
use crate::palette::Palette;
use crate::rng::Rng;
use crate::wet::Paint;
use rayon::prelude::*;

type Field<'a, T> = Box<dyn Fn(f32, f32) -> T + Sync + 'a>;

/// The parameters of a stipple pass over a region (see the module docs).
pub struct Stipple<'a> {
    /// The brush (default `Tool::stippler(2.0)`): its width sets the mark size.
    pub tool: Tool,
    /// Peak pressure range; a random value in it per touch. Harder touches
    /// make bigger, fuller marks, so this is the mark-size variation.
    pub pressure: (f32, f32),
    /// Coverage: how many touches fall on each point on average (a touch
    /// covers about π(0.4·width)²). Where it is higher the stipple is denser
    /// and its color stronger.
    pub coverage: Field<'a, f32>,
    /// The target color at a point, on the canvas (with `aim`, the paint is
    /// mixed so that a touch there dries to this; see `paint_for`).
    pub color: Field<'a, Rgb>,
    /// A color relative to what is on the canvas (see `color_over`); when
    /// set, it replaces `color`.
    pub color_over: Option<crate::handling::OverField<'a>>,
    /// Mix each pile from these tubes, thinned with this fraction of medium.
    pub palette: Option<(&'a Palette, f32)>,
    /// Hiding and stiffness of the paint without a palette.
    pub hiding: f32,
    pub stiff: f32,
    /// Palette-mixing inconsistency per dip: OKLab L and a/b sd (no palette).
    pub jitter: (f32, f32),
    /// Relative sd of the tube proportions per dip (palette).
    pub mix_jitter: f32,
//! Drawing on the ground: graphite pencils and black chalk.
//!
//! The model, from first principles and kept simple:
//! - **A point dragged over the tooth.** The point rides on the local tops of
//!   the ground (the weave showing through it); pressure lets it bite down
//!   into the hollows. A light line catches only the tops and breaks up into
//!   the grain of the canvas; a heavy one fills in.
//! - **Hardness** is the ratio of clay to graphite in the lead. A hard pencil
//!   (2H) lays less, of a lighter gray, and stays sharp; a soft one (4B) lays
//!   more, darker and glossier, and blunts fast (lines widen as it wears).
//!   Black chalk (carbon black in clay) is a deep matte black, crumbly and
//!   broad.
//! - **Optics.** The deposit covers a fraction `a` of each pixel with flakes of
//!   reflectance `r`; the ground shows between them. It is written into the
//!   dry picture, so every later layer of paint composites over it by
//!   Kubelka–Munk (`Pigment::over`): a thin veil lets it show, body color
//!   hides it. Graphite doesn't take on wet paint.
//! - **Loose until painted over.** A kneaded eraser lifts it, better from the
//!   tops than the hollows and never quite all of it; fixative binds it so the
//!   eraser no longer lifts it; once paint has gone over it, it is sealed in
//!   the picture.
//!
//! The bookkeeping (`Drawing`) exists only on a canvas that has been drawn
//! on, so paintings without a drawing are unchanged.

use crate::canvas::Canvas;
use crate::color::Rgb;
use crate::mask::Mask;
use crate::path::arclen;
use crate::rng::{Rng, hash2};
use crate::surface::vnoise;

/// What a point is made of.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Medium {
    Graphite,
    Chalk,
}

/// A drawing point: a graphite pencil of some grade, or black chalk.
#[derive(Clone, Debug)]
pub struct Lead {
    pub medium: Medium,
    /// Grade as softness: 2H = -2, H = -1, F = -0.5, HB = 0, B = 1, 4B = 4.
    pub soft: f32,
    /// Reflectance of the laid flakes (linear, gray).
    pub flake: f32,
    /// Coverage laid in one pass at full contact and pressure (fraction of
    /// what is still bare).
    pub rate: f32,
    /// Most of a pixel's area the deposit can cover.
    pub cap: f32,
    /// Width of the sharpened point, mm.
    pub point_mm: f32,
    /// Length of line (mm) over which the point blunts (width grows toward 3×).
    pub blunt_mm: f32,
    /// How deep into the tooth the point reaches at full pressure, µm.
    pub bite_um: f32,
    /// Irregularity of the deposit (0 smooth, 1 crumbly).
    pub crumble: f32,
