use paint::{Style, hex, shift, color::linear_to_srgb};
fn h(c: paint::Rgb) -> String { format!("#{:02x}{:02x}{:02x}", (linear_to_srgb(c[0])*255.0) as u8, (linear_to_srgb(c[1])*255.0) as u8, (linear_to_srgb(c[2])*255.0) as u8) }
fn main() {
    let st = Style::friedrich();
    let pal = st.palette.clone();
    for (name, under, want, med, coats) in [
        ("veil", hex("#c9c3b8"), shift(hex("#c9c3b8"), -0.07, 0.0, 0.0), 0.7f32, 3.0f32),
        ("sail", hex("#e3d0ad"), hex("#8a8189"), 0.15, 8.0),
        ("refl", hex("#8a8173"), shift(hex("#8a8173"), -0.07, 0.0, -0.01), 0.4, 8.0),
        ("grass lit", hex("#6c624f"), hex("#6f6a52"), 0.15, 1.0),
    ] {
        let m = pal.aim(want, under, med, coats);
        let p = m.paint(med);
        println!("{name}: want {} under {} -> {} masstone {} look@coats {} look@1 {} look@0.3 {}", h(want), h(under), pal.recipe(&m), h(m.color), h(p.over(under, coats)), h(p.over(under, 1.0)), h(p.over(under, 0.3)));
        let q = pal.paint(want, med);
        println!("   plain mix: masstone {} look@1 over under {}", h(q.color), h(q.over(under, 1.0)));
    }
}
